def norm(lang: str | None) -> str:
    return "en" if (lang or "").lower().startswith("en") else "es"


def msg(lang: str | None, key: str, **kw) -> str:
    table = MESSAGES[norm(lang)]
    return table.get(key, MESSAGES["es"].get(key, key)).format(**kw)


